        for (const c of el.children) {
          const cs = getComputedStyle(c);
          if (cs.display === 'contents') { walk(c); continue; }
          if (cs.display === 'none') continue;
          const b = c.getBoundingClientRect();
          if (b.width === 0 && b.height === 0) continue;
          items.push({ tag: c.id || c.className || c.tagName, top: Math.round(b.top), left: Math.round(b.left), w: Math.round(b.width), h: Math.round(b.height) });
        }
      };
      walk(bar);
      const tops = [...new Set(items.map(i => i.top))].sort((a,b)=>a-b);
