        width: Math.floor(window.innerWidth),
        height: Math.floor(window.innerHeight - top),
        barH: Math.round(bar.height),
        wrapped: (() => {
          const speed = document.querySelector('.pb-speed').getBoundingClientRect();
          return speed.top - bar.top > 20;
        })(),
        scroll: document.getElementById('playbackBar').scrollWidth - document.getElementById('playbackBar').clientWidth,
      };
    });
    console.log('live', w, clip);
    await page.screenshot({
      path: path.join(out, `desktop-playback-bar-wrap-${w}-live.png`),
      clip: { x: clip.x, y: clip.y, width: clip.width, height: clip.height },
    });
    await page.close();
  }

  // Mobile regression: dock still present, desktop bar hidden
  {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await page.goto('http://127.0.0.1:5051/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    await page.evaluate(() => localStorage.setItem('simplify-viewer-tour-v1', '1'));
    await page.reload({ waitUntil: 'domcontentloaded' });
    await page.evaluate(() => {
      document.body.classList.add('trace-loaded-mobile', 'playback-ready');
      const dock = document.getElementById('mobileTransport');
      if (dock) dock.style.display = '';
    });
    const m = await page.evaluate(() => {
      const bar = document.getElementById('playbackBar');
      const dock = document.getElementById('mobileTransport');
      return {
        barDisplay: getComputedStyle(bar).display,
        dockExists: !!dock,
        dockDisplay: dock ? getComputedStyle(dock).display : null,
      };
    });
    console.log('mobile', m);
    await page.screenshot({ path: path.join(out, 'desktop-playback-bar-wrap-390-regression-live.png') });
    await page.close();
  }

  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
